(()=>{
    cookie = cookie.getCookie(source.key);
    referer = source.key + "/";

    var headers = {
        "User-Agent": "Mozilla/5.0 (Linux; Android 10; SK) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Mobile Safari/537.36",
        "Referer": referer,
        "cookie": cookie
    }; 
    return JSON.stringify(headers);
})()

